import sys
import json
from typing import List

class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)
        top = [0] * n
        bottom = [0] * n

        # Columns with sum 2 are forced to be [1, 1].
        for i, value in enumerate(colsum):
            if value == 2:
                top[i] = 1
                bottom[i] = 1
                upper -= 1
                lower -= 1

        if upper < 0 or lower < 0:
            return []

        # Columns with sum 1 contribute exactly one 1.
        for i, value in enumerate(colsum):
            if value == 1:
                if upper > 0:
                    top[i] = 1
                    upper -= 1
                else:
                    bottom[i] = 1
                    lower -= 1

        return [top, bottom] if upper == 0 and lower == 0 else []

