static int next_int(const char **p) {
    while (**p && !isdigit((unsigned char)**p)) {
        (*p)++;
    }
    int value = 0;
    while (**p && isdigit((unsigned char)**p)) {
        value = value * 10 + (**p - '0');
        (*p)++;
    }
    return value;
}

/*
 * Return a 2-row matrix.
 * returnSize is set to 0 for an impossible instance.
 * On success, *returnColumnSizes contains the two row lengths.
 */
int** reconstructMatrix(int upper, int lower, int* colsum, int colsumSize,
                        int* returnSize, int** returnColumnSizes) {
    int **result = (int**)malloc(2 * sizeof(int*));
    result[0] = (int*)calloc((size_t)colsumSize, sizeof(int));
    result[1] = (int*)calloc((size_t)colsumSize, sizeof(int));

    for (int i = 0; i < colsumSize; ++i) {
        if (colsum[i] == 2) {
            result[0][i] = 1;
            result[1][i] = 1;
            --upper;
            --lower;
        }
    }

    if (upper < 0 || lower < 0) {
        free(result[0]);
        free(result[1]);
        free(result);
        *returnSize = 0;
        *returnColumnSizes = NULL;
        return NULL;
    }

    for (int i = 0; i < colsumSize; ++i) {
        if (colsum[i] == 1) {
            if (upper > 0) {
                result[0][i] = 1;
                --upper;
            } else {
                result[1][i] = 1;
                --lower;
            }
        }
    }

    if (upper != 0 || lower != 0) {
        free(result[0]);
        free(result[1]);
        free(result);
        *returnSize = 0;
        *returnColumnSizes = NULL;
        return NULL;
    }

    *returnSize = 2;
    *returnColumnSizes = (int*)malloc(2 * sizeof(int));
    (*returnColumnSizes)[0] = colsumSize;
    (*returnColumnSizes)[1] = colsumSize;
    return result;
}

int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) {
        return 0;
    }

    const char *p = line;
    int upper = next_int(&p);
    int lower = next_int(&p);

    int capacity = 16;
    int size = 0;
    int *colsum = (int*)malloc((size_t)capacity * sizeof(int));

    while (*p) {
        while (*p && !isdigit((unsigned char)*p)) {
            ++p;
        }
        if (!*p) break;
        int value = next_int(&p);
        if (size == capacity) {
            capacity *= 2;
            colsum = (int*)realloc(colsum, (size_t)capacity * sizeof(int));
        }
        colsum[size++] = value;
    }

    int returnSize = 0;
    int *returnColumnSizes = NULL;
    int **result = reconstructMatrix(upper, lower, colsum, size,
                                     &returnSize, &returnColumnSizes);

    printf("[");
    for (int i = 0; i < returnSize; ++i) {
        if (i) printf(",");
        printf("[");
        for (int j = 0; j < returnColumnSizes[i]; ++j) {
            if (j) printf(",");
            printf("%d", result[i][j]);
        }
        printf("]");
    }
    printf("]\n");

    if (result) {
        free(result[0]);
        free(result[1]);
        free(result);
    }
    free(returnColumnSizes);
    free(colsum);
    return 0;
}

