static vector<int> extractInts(const string& s) {
    vector<int> nums;
    for (size_t i = 0; i < s.size();) {
        if (isdigit(static_cast<unsigned char>(s[i]))) {
            int value = 0;
            while (i < s.size() && isdigit(static_cast<unsigned char>(s[i]))) {
                value = value * 10 + (s[i] - '0');
                ++i;
            }
            nums.push_back(value);
        } else {
            ++i;
        }
    }
    return nums;
}

