import java.io.*;
import java.util.*;

class Solution {
    public List<List<Integer>> reconstructMatrix(int upper, int lower, int[] colsum) {
        int n = colsum.length;
        int[] top = new int[n];
        int[] bottom = new int[n];

        for (int i = 0; i < n; i++) {
            if (colsum[i] == 2) {
                top[i] = 1;
                bottom[i] = 1;
                upper--;
                lower--;
            }
        }

        if (upper < 0 || lower < 0) {
            return new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            if (colsum[i] == 1) {
                if (upper > 0) {
                    top[i] = 1;
                    upper--;
                } else {
                    bottom[i] = 1;
                    lower--;
                }
            }
        }

        if (upper != 0 || lower != 0) {
            return new ArrayList<>();
        }

        List<Integer> first = new ArrayList<>(n);
        List<Integer> second = new ArrayList<>(n);
        for (int value : top) first.add(value);
        for (int value : bottom) second.add(value);

        List<List<Integer>> result = new ArrayList<>(2);
        result.add(first);
        result.add(second);
        return result;
    }
}

public class Main {
    private static int pos;
    private static String raw;

    private static String nextToken() {
        while (pos < raw.length() && (raw.charAt(pos) == ' ' || raw.charAt(pos) == ',')) {
            pos++;
        }
        if (pos >= raw.length()) return "";
        if (raw.charAt(pos) == '[') {
            int start = pos;
            int depth = 0;
            while (pos < raw.length()) {
                char c = raw.charAt(pos++);
                if (c == '[') depth++;
                else if (c == ']') {
                    depth--;
                    if (depth == 0) break;
                }
            }
            return raw.substring(start, pos);
        }
        int start = pos;
        while (pos < raw.length() && raw.charAt(pos) != ',' && raw.charAt(pos) != ']') {
            pos++;
        }
        return raw.substring(start, pos).trim();
    }

    private static int[] parseIntArray(String token) {
        String s = token.trim();
        if (s.equals("[]")) return new int[0];
        s = s.substring(1, s.length() - 1).trim();
        if (s.isEmpty()) return new int[0];

        ArrayList<Integer> values = new ArrayList<>();
        int i = 0;
        while (i < s.length()) {
            while (i < s.length() && (s.charAt(i) == ' ' || s.charAt(i) == ',')) i++;
            if (i >= s.length()) break;
            int start = i;
            while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            values.add(Integer.parseInt(s.substring(start, i)));
        }

        int[] result = new int[values.size()];
        for (i = 0; i < values.size(); i++) result[i] = values.get(i);
        return result;
    }

    private static String serialize(List<List<Integer>> result) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append('[');
            for (int j = 0; j < result.get(i).size(); j++) {
                if (j > 0) sb.append(',');
                sb.append(result.get(i).get(j));
            }
            sb.append(']');
        }
        sb.append(']');
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        raw = line.substring(1, line.length() - 1);
        pos = 0;

        int upper = Integer.parseInt(nextToken());
        int lower = Integer.parseInt(nextToken());
        int[] colsum = parseIntArray(nextToken());

        List<List<Integer>> result = new Solution().reconstructMatrix(upper, lower, colsum);
        System.out.println(serialize(result));
    }
}

