const readline = require('readline');

/**
 * @param {number} upper
 * @param {number} lower
 * @param {number[]} colsum
 * @return {number[][]}
 */
var reconstructMatrix = function(upper, lower, colsum) {
    const n = colsum.length;
    const top = Array(n).fill(0);
    const bottom = Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        if (colsum[i] === 2) {
            top[i] = 1;
            bottom[i] = 1;
            upper--;
            lower--;
        }
    }

    if (upper < 0 || lower < 0) {
        return [];
    }

    for (let i = 0; i < n; i++) {
        if (colsum[i] === 1) {
            if (upper > 0) {
                top[i] = 1;
                upper--;
            } else {
                bottom[i] = 1;
                lower--;
            }
        }
    }

    return upper === 0 && lower === 0 ? [top, bottom] : [];
};

